function Init([string]$p){if(-not [IO.Directory]::Exists($p)){[void][IO.Directory]::CreateDirectory($p)}}
function Text([string]$n,[AllowEmptyString()][string]$v){$p=Join-Path $EvidenceRoot $n;Init ([IO.Path]::GetDirectoryName($p));[IO.File]::WriteAllText($p,$v,(New-Object Text.UTF8Encoding($false)))}
function Json([string]$n,$v){Text $n (($v|ConvertTo-Json -Depth 20)+[Environment]::NewLine)}
function Sha([string]$p){$h=[Security.Cryptography.SHA256]::Create();$s=[IO.File]::OpenRead($p);try{return ([BitConverter]::ToString($h.ComputeHash($s))).Replace('-','').ToUpperInvariant()}finally{$s.Dispose();$h.Dispose()}}
function Native([string]$e,[string[]]$a,[string]$label,[switch]$Progress){$err=Join-Path $env:TEMP ('p5-'+[guid]::NewGuid().ToString('N')+'.err');try{$o=@(& $e @a 2>$err);$c=$LASTEXITCODE;$s=($o|ForEach-Object{[string]$_})-join [Environment]::NewLine;$r='';if([IO.File]::Exists($err)){$r=[IO.File]::ReadAllText($err)};[void]$Actions.Add([pscustomobject]@{Action=$label;ExitCode=$c});if($c-ne 0){throw ('APEX_NATIVE_FAILED:{0}:{1}' -f $label,$c)};if((-not $Progress)-and $r -match '(?i)error|fatal|failed|exception'){throw ('APEX_NATIVE_STDERR:{0}' -f $label)};return [pscustomobject]@{Stdout=$s;Stderr=$r;ExitCode=$c}}finally{if(Test-Path $err){Remove-Item $err -Force -ErrorAction SilentlyContinue}}}
function Inspect([string]$id){@(Native $docker @('inspect',$id) 'INSPECT').Stdout|ConvertFrom-Json|Select-Object -First 1}
