function Rows(){ $r=Native $docker @('ps','--filter','label=com.docker.compose.project=frappe_docker','--format','{{.ID}}') 'CENSUS';$out=foreach($id in @($r.Stdout -split '\r?\n'|Where-Object{$_.Trim()})){ $i=Inspect $id;$networkNames=@($i.NetworkSettings.Networks.PSObject.Properties|Select-Object -ExpandProperty Name);$portNames=@($i.NetworkSettings.Ports.PSObject.Properties|Select-Object -ExpandProperty Name);[pscustomobject]@{Container=$i.Name.TrimStart('/');Service=(Service $i);Image=[string]$i.Config.Image;State=(State $i);RestartCount=[int]$i.RestartCount;Networks=($networkNames-join '|');Ports=($portNames-join '|')}};return @($out)}
function Stable([string]$svc){$ids=@((Native $docker @('ps','-aq','--filter',"label=com.docker.compose.service=$svc",'--filter','label=com.docker.compose.project=frappe_docker') "IDS_$svc").Stdout -split '\r?\n'|Where-Object{$_.Trim()});if($ids.Count-ne 1){throw "APEX_PHASE5_CONTAINER_CARDINALITY:$svc"};$i=Inspect $ids[0];$networkNames=@($i.NetworkSettings.Networks.PSObject.Properties|Select-Object -ExpandProperty Name);$published=($i.NetworkSettings.Ports|ConvertTo-Json -Compress);if((State $i)-ne 'running' -or [string]$i.Config.Image-ne $Image -or $networkNames-notcontains $Network){throw "APEX_PHASE5_RUNTIME_INVALID:$svc"};if($svc-eq 'frontend' -and ($published-match '0\.0\.0\.0|\[::\]' -or $published-notmatch '127\.0\.0\.1.*18081')){throw 'APEX_PHASE5_FRONTEND_PUBLIC_BIND'};if($svc-eq 'websocket' -and ($published-match '0\.0\.0\.0|\[::\]' -or $published-notmatch '127\.0\.0\.1.*18082')){throw 'APEX_PHASE5_WEBSOCKET_PUBLIC_BIND'};$before=[int]$i.RestartCount;Start-Sleep 5;$i=Inspect $ids[0];if([int]$i.RestartCount-ne $before){throw "APEX_PHASE5_RESTART_INSTABILITY:$svc"};return [pscustomobject]@{status='PASS';service=$svc;container=$ids[0];restartCount=$before}}
function StartAdopt([string]$svc){$ids=@((Native $docker @('ps','-aq','--filter',"label=com.docker.compose.service=$svc",'--filter','label=com.docker.compose.project=frappe_docker') "RESUME_$svc").Stdout -split '\r?\n'|Where-Object{$_.Trim()});if($ids.Count-eq 1 -and (State (Inspect $ids[0]))-eq 'running'){try{return [pscustomobject]@{adopted='YES';started='NO';runtime=(Stable $svc)}}catch{}};try{[void](Native $docker @('compose','-p',$Project,'-f',$Compose,'-f',$Override,'up','-d','--no-deps','--force-recreate',$svc) "START_$svc" -Progress)}catch{if(@((Native $docker @('ps','-aq','--filter',"label=com.docker.compose.service=$svc",'--filter','label=com.docker.compose.project=frappe_docker') "POSTSTATE_$svc").Stdout -split '\r?\n'|Where-Object{$_.Trim()}).Count-ne 1){throw}};return [pscustomobject]@{adopted='NO';started='YES';runtime=(Stable $svc)}}
function HashSites(){ $r=Native $docker @('run','--rm','--network','none','--mount','type=volume,source=frappe_docker_sites,target=/sites,readonly','--entrypoint','sh',$Image,'-c','for p in /sites/frontend/site_config.json /sites/common_site_config.json /sites/apps.txt /sites/apps.json; do sha256sum "$p"; done') 'SITE_HASHES';return @($r.Stdout-split '\r?\n'|Where-Object{$_.Trim()}|ForEach-Object{$x=$_-split '\s+',2;[pscustomobject]@{Path=$x[1];Sha256=$x[0].ToUpperInvariant()}})}
